class Solution {
public:
    vector<vector<int>> highestRankedKItems(vector<vector<int>>& grid, vector<int>& pricing, vector<int>& start, int k) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> dist(m, vector<int>(n, -1));
        queue<pair<int,int>> q;
        dist[start[0]][start[1]] = 0;
        q.push({start[0], start[1]});
        vector<array<int,4>> cand;
        int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
        while (!q.empty()) {
            auto [r, c] = q.front();
            q.pop();
            if (grid[r][c] >= pricing[0] && grid[r][c] <= pricing[1])
                cand.push_back({dist[r][c], grid[r][c], r, c});
            for (int t = 0; t < 4; t++) {
                int nr = r + dr[t], nc = c + dc[t];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] > 0 && dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[r][c] + 1;
                    q.push({nr, nc});
                }
            }
        }
        sort(cand.begin(), cand.end());
        vector<vector<int>> res;
        for (int i = 0; i < (int)cand.size() && i < k; i++)
            res.push_back({cand[i][2], cand[i][3]});
        return res;
    }
};

