class Solution {
    public List<List<Integer>> highestRankedKItems(int[][] grid, int[] pricing, int[] start, int k) {
        int m = grid.length, n = grid[0].length;
        int[][] dist = new int[m][n];
        for (int[] row : dist) Arrays.fill(row, -1);
        Deque<int[]> q = new ArrayDeque<>();
        dist[start[0]][start[1]] = 0;
        q.offer(new int[]{start[0], start[1]});
        List<int[]> cand = new ArrayList<>();
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];
            if (grid[r][c] >= pricing[0] && grid[r][c] <= pricing[1])
                cand.add(new int[]{dist[r][c], grid[r][c], r, c});
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] > 0 && dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[r][c] + 1;
                    q.offer(new int[]{nr, nc});
                }
            }
        }
        cand.sort((a, b) -> {
            for (int i = 0; i < 4; i++)
                if (a[i] != b[i]) return Integer.compare(a[i], b[i]);
            return 0;
        });
        List<List<Integer>> res = new ArrayList<>();
        for (int i = 0; i < Math.min(k, cand.size()); i++)
            res.add(Arrays.asList(cand.get(i)[2], cand.get(i)[3]));
        return res;
    }
}

