            items = []
            nxt = []
            for r, c in frontier:
                if low <= grid[r][c] <= high:
                    items.append((grid[r][c], r, c))
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] > 0 and not seen[nr][nc]:
