        int m = grid.length, n = grid[0].length;
        boolean[][] seen = new boolean[m][n];
        seen[start[0]][start[1]] = true;
        List<int[]> frontier = new ArrayList<>();
        frontier.add(new int[]{start[0], start[1]});
        List<List<Integer>> res = new ArrayList<>();
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!frontier.isEmpty() && res.size() < k) {
            List<int[]> items = new ArrayList<>();
            List<int[]> nxt = new ArrayList<>();
            for (int[] cell : frontier) {
                int r = cell[0], c = cell[1];
                if (grid[r][c] >= pricing[0] && grid[r][c] <= pricing[1])
                    items.add(new int[]{grid[r][c], r, c});
                for (int[] d : dirs) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] > 0 && !seen[nr][nc]) {
                        seen[nr][nc] = true;
                        nxt.add(new int[]{nr, nc});
                    }
                }
            }
            items.sort((x, y) -> x[0] != y[0] ? x[0] - y[0] : x[1] != y[1] ? x[1] - y[1] : x[2] - y[2]);
            for (int[] it : items) {
                res.add(Arrays.asList(it[1], it[2]));
                if (res.size() == k) break;
            }
            frontier = nxt;
        }
        return res;
    }
}

